mapper.select:
select mn.*, isa.sa_title as saTitle, sc3.C_NAME AS constructionContractorName, isa.sa_serial_number AS invSettlementSerialNumber, ccc.confirm_serial_number AS confirmSerialNumber, ccc.Construction_Drawing AS constructionDrawing, ccc.Construction_Image AS constructionImage, ccc.Construction_Contractor AS constructionContractor, isa.sa_amount_total AS saAmountTotal, isa.Sa_Approved_Amt AS saApprovedAmt, isa.sa_increase_decrease AS saIncreaseDecrease, isa.sa_report_file AS saReportFile, isa.sa_audit_report AS saAuditReport, ccc.Audit_Unit AS auditUnit, sc2.C_NAME AS auditUnitName from inv_settlement_pay mn left join construction_completion_confirm ccc on ccc.id = mn.confirm_complete_id left join inv_settlement_apply isa on isa.Sa_Id = mn.inv_settlement_apply_id left join sys_company sc3 on sc3.C_ID = ccc.Construction_Contractor left join sys_company sc2 on sc2.C_ID = ccc.Audit_Unit ${params.authSql}
and isa.sa_serial_number like concat('%',#{params.invSettlementSerialNumber},'%')
and ccc.confirm_serial_number like concat('%',#{params.confirmSerialNumber},'%')
and mn.Create_Time between #{params.createTimeRange[0]} and #{params.createTimeRange[1]}
and mn.state = #{params.state}
and sc3.C_NAME like concat('%',#{params.constructionContractorName},'%')
and isa.sa_title like concat('%',#{params.saTitle},'%')
and not exists ( select 1 from application_warranty aw where aw.isp_id = mn.id and aw.state != 3 )
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc
